#include <iostream>
#include <cmath>

bool isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    for (int i = 2; i * i <= number; ++i) {
        if (number % i == 0) {
            return false;
        }
    }
    return true;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, m;
    if (!(std::cin >> n >> m)) {
        return 0;
    }

    for (int i = n + 1; i <= m; ++i) {
        if (isPrime(i)) {
            if (i == m) {
                std::cout << "YES" << std::endl;
            } else {
                std::cout << "NO" << std::endl;
            }
            return 0;
        }
    }

    std::cout << "NO" << std::endl;
    return 0;
}

